 75→export function createReviewDecision(data: {
 76→  requestId: number;
 77→  candidateId: number;
 78→  stepKey: string;
 79→  reviewerId: number;
 80→  decision?: string | null;
 81→  comment?: string | null;
 82→  reviewDataJson?: string;
 83→}): ReviewDecision {
 84→  const db = getDb();
 85→  const stmt = db.prepare(`
 86→    INSERT INTO review_decisions (request_id, candidate_id, step_key, reviewer_id, decision, comment, review_data_json)
 87→    VALUES (?, ?, ?, ?, ?, ?, ?)
 88→    ON CONFLICT(request_id, candidate_id, step_key, reviewer_id)
 89→    DO UPDATE SET
 90→      decision = excluded.decision,
 91→      comment = excluded.comment,
 92→      review_data_json = excluded.review_data_json,
 93→      updated_at = CURRENT_TIMESTAMP
 94→  `);
 95→
 96→  const result = stmt.run(
 97→    data.requestId,
 98→    data.candidateId,
 99→    data.stepKey,
100→    data.reviewerId,
101→    data.decision ?? null,
102→    data.comment ?? null,
103→    data.reviewDataJson ?? "{}"
104→  );
105→
106→  // On conflict, the rowid returned is 0; fetch by unique key instead
107→  if (result.changes > 0 && result.lastInsertRowid === 0) {
108→    const row = db
109→      .prepare(
110→        "SELECT * FROM review_decisions WHERE request_id = ? AND candidate_id = ? AND step_key = ? AND reviewer_id = ?"
111→      )
112→      .get(data.requestId, data.candidateId, data.stepKey, data.reviewerId) as ReviewDecisionRow;
113→    return mapRow(row);
114→  }
115→
116→  return getReviewDecisionById(Number(result.lastInsertRowid))!;
117→}
