125→  }
126→): ReviewDecision | null {
127→  const db = getDb();
128→
129→  const fields: string[] = [];
130→  const values: unknown[] = [];
131→
132→  if (data.decision !== undefined) {
133→    fields.push("decision = ?");
134→    values.push(data.decision);
