import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import {
  getReviewDecisions,
  createReviewDecision,
} from "@/lib/review-decisions";

export async function GET(req: NextRequest) {
  const user = await requireUser();

  const { searchParams } = req.nextUrl;
  const requestId = searchParams.get("requestId");
  if (!requestId) {
    return NextResponse.json(
      { error: "requestId is required" },
      { status: 400 },
    );
  }

  const stepKey = searchParams.get("stepKey") ?? undefined;
  const decisions = getReviewDecisions(Number(requestId), stepKey);
  return NextResponse.json(decisions);
}

export async function POST(req: NextRequest) {
  const user = await requireUser();
  if (!checkPermission(user.role, "workflow.review", "edit")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const body = (await req.json()) as {
    requestId: number;
    candidateId: number;
    stepKey: string;
    decision?: string | null;
    comment?: string | null;
    reviewDataJson?: string;
  };

  const record = createReviewDecision({
    requestId: body.requestId,
    candidateId: body.candidateId,
    stepKey: body.stepKey,
    reviewerId: user.id,
    decision: body.decision,
    comment: body.comment,
    reviewDataJson: body.reviewDataJson,
  });

  return NextResponse.json(record, { status: 201 });
}

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { updateReviewDecision } from "@/lib/review-decisions";

type RouteContext = {
  params: Promise<{ id: string }>;
};

export async function PATCH(req: NextRequest, context: RouteContext) {
  const user = await requireUser();
  if (!checkPermission(user.role, "workflow.review", "edit")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const { id } = await context.params;

  const body = (await req.json()) as {
    decision?: string | null;
    comment?: string | null;
    reviewDataJson?: string;
  };

  const updated = updateReviewDecision(Number(id), body);
  if (!updated) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  return NextResponse.json(updated);
}

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { getDb } from "@/lib/db";
import { getProcedureType, PROCEDURE_STEPS } from "@/lib/constants";
import { getNextStatus } from "@/lib/workflow";
import { allCandidatesReviewed } from "@/lib/review-decisions";

export async function POST(req: NextRequest) {
  const user = await requireUser();
  if (!checkPermission(user.role, "workflow.advance", "edit")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const body = (await req.json()) as { requestId: number };
  const db = getDb();

  const request = db
    .prepare(
      "SELECT id, hiring_type as hiringType, status FROM recruitment_requests WHERE id = ?",
    )
    .get(body.requestId) as
    | { id: number; hiringType: string; status: string }
    | undefined;

  if (!request) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const procedureType = getProcedureType(request.hiringType);
  const steps = PROCEDURE_STEPS[procedureType];
  const currentStep = steps.find((s) => s.stepKey === request.status);

  if (!currentStep) {
    return NextResponse.json(
      { error: "현재 단계를 찾을 수 없습니다" },
      { status: 400 },
    );
  }

  if (!allCandidatesReviewed(body.requestId, currentStep.stepKey)) {
    return NextResponse.json(
      { error: "모든 후보자 심사를 완료해주세요" },
      { status: 400 },
    );
  }

  const nextStatus = getNextStatus(request.hiringType, request.status);
  if (!nextStatus) {
    return NextResponse.json(
      { error: "이미 마지막 단계입니다" },
      { status: 400 },
    );
  }

  db.prepare(
    "UPDATE recruitment_requests SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
  ).run(nextStatus, body.requestId);

  return NextResponse.json({ success: true, newStatus: nextStatus });
}
